import { useEffect, useMemo, useRef, useState } from 'react';
import {
  Activity, ArrowDownRight, ArrowUpRight, Bell, BookOpen, Check, CheckCheck, ChevronDown,
  ChevronLeft, ChevronRight, CircleHelp, Clock3, CloudUpload, FileImage, FileText, Filter,
  Globe2, Image as ImageIcon, LayoutDashboard, LogIn, Menu, MoreHorizontal, Newspaper,
  Plus, Search, Settings, ShieldCheck, Sparkles, TrendingUp, Upload, Users, X, Eye,
  CalendarDays, CheckCircle2, AlertCircle, Languages, PanelLeftClose, ArrowRight, ExternalLink,
  Save, Send, Trash2, ZoomIn, ZoomOut, Maximize2, Move, Crop, Layers3, Megaphone, RefreshCw,
  HardDrive, ImagePlus, CircleAlert, LoaderCircle, FileCheck2, Clock, ChevronUp,
} from 'lucide-react';

